    if (r.right > vw + 1 || r.left < -1) {
      offenders.push({ tag: el.tagName, cls: (el.className||'').toString().slice(0,50), left: Math.round(r.left), right: Math.round(r.right), w: Math.round(r.width) });
    }
  });
  return {
    innerWidth: window.innerWidth,
    clientWidth: vw,
    bodyScrollWidth: b.scrollWidth,
    docScrollWidth: de.scrollWidth,
    scrollX: window.scrollX,
    horizontalOverflow: de.scrollWidth > vw,
    offenderCount: offenders.length,
    offenders: offenders.slice(0, 8)
  };
})()

