// 案例 26 修復：某些瀏覽器 inline onclick 第一次真實點擊不 fire（需 F5）。
// 把所有 inline onclick 轉成 addEventListener，一次綁定徹底解決「按了沒反應」。
function hardenButtons() {
    document.querySelectorAll('[onclick]').forEach(el => {
        const code = el.getAttribute('onclick');
        if (!code) return;
        el.removeAttribute('onclick');
        el.addEventListener('click', function(e) {
            try { new Function('event', code).call(this, e); }
            catch (err) { console.error('button handler error:', err); }
        });
    });
}

