(() => {
  const rm = document.getElementById('registerModal');
  const sm = document.getElementById('successModal');
  const lb = document.getElementById('lightbox');
  const isOpen = el => !el.classList.contains('hidden') && el.classList.contains('flex');
  const results = {};

  // 0) 乾淨起點
  hideRegisterModal(); hideSuccessModal();

  // 1) nav 報名按鈕 .click() → 開 modal
  document.querySelector('#navbar button.btn-primary').click();
  results['1_navBtnOpensModal'] = isOpen(rm);

  // 2) 填表送出 → success modal（非同步 800ms，這裡直接觸發 submit 後等檢查改用旗標）
  document.getElementById('name').value = '王小明';
  document.getElementById('phone').value = '0912345678';
  document.getElementById('email').value = 'a@b.com';
  document.getElementById('agree').checked = true;
  document.getElementById('registerForm').requestSubmit
    ? document.getElementById('registerForm').requestSubmit()
    : document.getElementById('registerForm').dispatchEvent(new Event('submit',{cancelable:true}));
  results['2_submitAccepted'] = true;

  // 3) 案例26：開著 modal 時點選單錨點，確認 modal 不被 remove
  hideSuccessModal();
  showRegisterModal();
  document.querySelector('a[href="#pitfalls"]').click();
  results['3_modalSurvivesAnchorClick'] = !!document.getElementById('registerModal');
  hideRegisterModal();

  // 4) gallery thumb → lightbox 開且 src 正確
  document.querySelector('#slideGallery .slide-thumb').click();
  results['4_lightboxOpens'] = isOpen(lb);
  results['4_lightboxSrc'] = document.getElementById('lightboxImg').getAttribute('src');
  closeLightbox();
  results['4_lightboxCloses'] = !isOpen(lb);

  // 5) 壞圖檢查（排除 lightbox 空 src）
  results['5_brokenImgs'] = [...document.querySelectorAll('img')]
    .filter(i => i.complete && i.naturalWidth === 0 && i.getAttribute('src'))
    .map(i => i.src);

  // 6) gallery 數量
  results['6_galleryCount'] = document.querySelectorAll('#slideGallery img').length;

  hideRegisterModal(); hideSuccessModal();
  return results;
})()

(() => {
  const de = document.documentElement;
  const vw = de.clientWidth;
  // 水平溢出檢查
  const overflow = de.scrollWidth > vw + 1;
  const offenders = [];
  if (overflow) {
    document.querySelectorAll('*').forEach(el => {
      const r = el.getBoundingClientRect();
      if (r.right > vw + 1) offenders.push({ tag: el.tagName, cls:(el.className||'').toString().slice(0,40), right: Math.round(r.right) });
    });
  }
  // 漢堡選單按鈕（md:hidden → 手機可見）
  const hamburger = document.querySelector('#navbar button.md\\:hidden');
  const hbVisible = hamburger && getComputedStyle(hamburger).display !== 'none';
  // 開漢堡選單測試
  hamburger && hamburger.click();
  const menuOpen = !!document.querySelector('.fixed.inset-0.bg-black\\/60');
  document.querySelectorAll('.fixed.inset-0.bg-black\\/60').forEach(m=>m.remove());
  return {
    viewportWidth: vw,
    horizontalOverflow: overflow,
    offenders: offenders.slice(0,6),
    hamburgerVisible: hbVisible,
    mobileMenuOpens: menuOpen
  };
})()
